head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst60207";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst60207.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return "주식워런트 발행자료 : " + String(dma_detailMain.get("comNm")) + "(" + String(dma_detailMain.get("comEngNm")) + ")[" + String(dma_detailMain.get("comAbbrv")) + "]"; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function () {
    await scwin.tx_init_ajaxsubmit();
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        $c.util.getComponent("dma_initAjaxsubmitReq").set("method", "readRightWarrantCodeDetailedSub");
        $c.util.getComponent("dma_initAjaxsubmitReq").set("forward", "rightwarrantcodedetailed_sub");
        await scwin.init();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst60207.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_init_ajaxsubmit
 * @description init ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_init_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_init_ajaxsubmit",
        method: "post",
        action: "/disclosure/readrightwarrantcodedetailed.do",
        ref: "dma_initAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnSearch_ajaxsubmit
 * @description fn Search ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearch_ajaxsubmit",
        method: "post",
        action: "/disclosure/readrightwarrantcodedetailed.do",
        ref: "dma_fnSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @param {String} ipt_strIsuCd ipt_strIsuCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function (ipt_strIsuCd) {
    $c.util.getComponent("dma_initAjaxsubmitReq").set("method", "readRightWarrantCodeDetailed");
    $c.util.getComponent("dma_initAjaxsubmitReq").set("forward", "rightwarrantcodedetailed");
    $c.util.getComponent("dma_initAjaxsubmitReq").set("strIsuCd", ipt_strIsuCd);
    await scwin.tx_fnSearch_ajaxsubmit();
};

/**
 * @method
 * @name fnSearchCallBack1
 * @description fn Search Call Back1 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchCallBack1 = function (data) {
    $("#leftContents").empty().append(data);
};

/**
 * @method
 * @name fnSearchCallBack2
 * @description fn Search Call Back2 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchCallBack2 = function (data) {
    $("#rightContents").empty().append(data);
};
